examples.template:
Form {
    MonarchBusinessHoursEditor(
        value: $hours,
        showsDefault: true,
        isNameRequired: true,
        isOpenRequired: true,
        showsErrors: saveTried,
        pinnedTimeZones: [{{pinnedTimeZones.0}}, {{pinnedTimeZones.1}}, {{pinnedTimeZones.2}}],
        firstWeekday: {{firstWeekday}},
        uses24HourClock: {{twentyFourHour}}
    ) {
        Section {
            Button({{save}}) {
                saveTried = true
                if hours.validate(isNameRequired: true, isOpenRequired: true).isValid { /* Save hours. */ }
            }
            .buttonStyle(.monarch(.primary))
        }
    }
}
.monarchCanvas()
.environment(\.locale, Locale(identifier: {{locale}}))

examples.setupTemplate:
@State private var hours = MonarchBusinessHoursValue(
    timeZone: {{timeZone}},
    hours: [{{weekdays.0}}, {{weekdays.1}}, {{weekdays.2}}, {{weekdays.3}}, {{weekdays.4}}].map {
        MonarchWeeklyHoursInterval(day: $0, start: {{start}}, end: {{end}})
    },
    exceptions: [
        MonarchBusinessHoursException(date: {{exceptions.0.date|date}}, name: {{exceptions.0.name}}),
        MonarchBusinessHoursException(
            date: {{exceptions.1.date|date}},
            name: {{exceptions.1.name}},
            intervals: [MonarchBusinessHoursInterval(start: {{exceptions.1.start}}, end: {{exceptions.1.end}})]
        ),
    ],
    name: {{name}}
)
@State private var saveTried = false

examples.setup:
@State private var hours = MonarchBusinessHoursValue(
    timeZone: "Europe/London",
    hours: [1, 2, 3, 4, 5].map {
        MonarchWeeklyHoursInterval(day: $0, start: 540, end: 1050)
    },
    exceptions: [
        MonarchBusinessHoursException(date: Date(timeIntervalSince1970: 1_798_156_800), name: "Christmas Day"),
        MonarchBusinessHoursException(
            date: Date(timeIntervalSince1970: 1_798_675_200),
            name: "New Year’s Eve",
            intervals: [MonarchBusinessHoursInterval(start: 540, end: 780)]
        ),
    ],
    name: "Support hours"
)
@State private var saveTried = false

examples.code:
Form {
    MonarchBusinessHoursEditor(
        value: $hours,
        showsDefault: true,
        isNameRequired: true,
        isOpenRequired: true,
        showsErrors: saveTried,
        pinnedTimeZones: ["Europe/London", "America/New_York", "Asia/Kolkata"],
        firstWeekday: 2,
        uses24HourClock: true
    ) {
        Section {
            Button("Save") {
                saveTried = true
                if hours.validate(isNameRequired: true, isOpenRequired: true).isValid { /* Save hours. */ }
            }
            .buttonStyle(.monarch(.primary))
        }
    }
}
.monarchCanvas()
.environment(\.locale, Locale(identifier: "en-GB"))

